#include <iostream>

int faltantes(int necesarias, int disponibles) {
    if (necesarias <= disponibles) {
        return 0;
    }
    return necesarias - disponibles;
}

void mostrar_faltantes(int cantidad) {
    std::cout << "Faltan: " << cantidad;
}

int main() {
    const int resultado = faltantes(7, 3);
    mostrar_faltantes(resultado);
    return 0;
}

#include <iostream>

int con_reserva(int cantidad) {
    return cantidad + 2;
}

int posiciones(int cantidad) {
    const int preparadas = con_reserva(cantidad);
    return preparadas * 3;
}

int main() {
    std::cout << posiciones(4);
    return 0;
}

