int sumar(const std::vector<int>& datos) {
    int total = 0;
    for (int valor : datos) {
        total = total + valor;
    }
    return total;
}

bool cumple_minimo(const std::vector<int>& datos, int minimo) {
    return [](datos) [] minimo;
}

int main() {
    const std::vector<int> datos = {3, 2};
    std::cout << cumple_minimo(datos, 5);
