#include <iostream>
#include <vector>

bool plan_valido(const std::vector<int>& pedidos, int capacidad, int reserva) {
    if (pedidos.size() > 6) {
        return false;
    }
    if ((capacidad < 1) || (capacidad > 10)
        || (reserva < 0) || (reserva > 3)) {
        return false;
    }
    for (int cantidad : pedidos) {
        if ((cantidad < 0) || (cantidad > 20)) {
            return false;
        }
    }
    return true;
}

int unidades_con_reserva(const std::vector<int>& pedidos, int reserva) {
    int unidades = reserva;
    for (int cantidad : pedidos) {
        unidades = unidades + cantidad;
    }
    return unidades;
}

int contenedores_necesarios(int unidades, int capacidad) {
    int contenedores = unidades / capacidad;
    if (unidades % capacidad != 0) {
        ++contenedores;
    }
    return contenedores;
}

void mostrar_plan(int unidades, int contenedores) {
    std::cout << "Unidades: " << unidades << "\n";
    std::cout << "Contenedores: " << contenedores << "\n";
}

int main() {
    int n{0};
    std::cin >> n;
    std::vector<int> pedidos;
    for (int i{0}; i < n; ++i) {
        int pedido{0};
        std::cin >> pedido;
        pedidos.push_back(pedido);
    }
    int capacidad{0};
    int reserva{0};
    std::cin >> capacidad >> reserva;
    if (plan_valido(pedidos, capacidad, reserva)) {
        const int unidades = unidades_con_reserva(pedidos, reserva);
        const int contenedores = contenedores_necesarios(unidades, capacidad);
        mostrar_plan(unidades, contenedores);
    } else {
        std::cout << "Datos fuera del dominio\n";
    }
    return 0;
}
